import 'server-only';
import { randomUUID } from 'node:crypto';
import { createReadStream } from 'node:fs';
import { mkdir, unlink, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { Readable } from 'node:stream';
import { env } from './env';

function root() {
  return path.resolve(env.uploadDir);
}

function resolveStored(storedName: string) {
  // storedName is always generated by us, but guard against path traversal anyway.
  const p = path.resolve(root(), storedName);
  if (!p.startsWith(root() + path.sep)) throw new Error('Invalid stored file name');
  return p;
}

export async function saveUpload(file: File) {
  await mkdir(root(), { recursive: true });
  const ext = path.extname(file.name).toLowerCase().replace(/[^a-z0-9.]/g, '').slice(0, 12);
  const storedName = `${randomUUID()}${ext}`;
  await writeFile(resolveStored(storedName), Buffer.from(await file.arrayBuffer()));
  return storedName;
}

export function openStoredFile(storedName: string) {
  return Readable.toWeb(createReadStream(resolveStored(storedName))) as ReadableStream;
}

export async function deleteStoredFile(storedName: string) {
  await unlink(resolveStored(storedName)).catch(() => {});
}
